"""Generate the additive evidence contract without changing shared crew schemas."""

import argparse
import json
from pathlib import Path

from app.nasa_evidence.models import EvidenceResponse

SCHEMA_PATH = Path(__file__).resolve().parents[2] / "schemas/nasa_evidence.schema.json"


def build_document() -> dict:
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$comment": "Generated by backend/scripts/export_nasa_evidence_schema.py; do not edit.",
        **EvidenceResponse.model_json_schema(),
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    document = build_document()
    if args.check:
        if not SCHEMA_PATH.is_file() or json.loads(SCHEMA_PATH.read_text()) != document:
            print(
                "NASA evidence schema is stale. Run python -m scripts.export_nasa_evidence_schema."
            )
            return 1
        print("NASA evidence schema is up to date.")
        return 0
    SCHEMA_PATH.write_text(json.dumps(document, indent=2) + "\n", encoding="utf-8", newline="\n")
    print("Wrote schemas/nasa_evidence.schema.json")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
